//
// Time complexity: O(1), space O(1).
#include <utility>
#include <algorithm>

// Returns {minimum possible number of connected components,
//          maximum possible number of bridges after minimizing components}
std::pair<long long, long long> countBridgesAndRoads(long long n, long long m) {
    long long minComponents;
    long long maxBridges;

    if (m < n - 1) {
        // Can connect at most m+1 vertices into one tree, rest isolated
        minComponents = n - m;
        maxBridges = m;
    } else {
        // Graph can be connected (one component)
        minComponents = 1;
        long long extra = m - (n - 1); // extra edges beyond a spanning tree
        long long half = (n - 1) / 2;  // maximum disjoint triangles possible
        if (extra <= half) {
            maxBridges = (n - 1) - 2 * extra;
        } else {
            maxBridges = 0;
        }
    }

    return {minComponents, maxBridges};
}
#include <cassert>
#include <utility>

// forward declaration of the solution (as if from header)
std::pair<long long, long long> countBridgesAndRoads(long long n, long long m);

int main() {
    // Basic cases
    assert(countBridgesAndRoads(1, 0) == std::make_pair(1LL, 0LL));
    assert(countBridgesAndRoads(3, 0) == std::make_pair(3LL, 0LL));
    assert(countBridgesAndRoads(3, 1) == std::make_pair(2LL, 1LL));
    assert(countBridgesAndRoads(3, 3) == std::make_pair(1LL, 0LL)); // complete graph K3

    // n=4
    assert(countBridgesAndRoads(4, 0) == std::make_pair(4LL, 0LL));
    assert(countBridgesAndRoads(4, 3) == std::make_pair(1LL, 3LL)); // a tree
    assert(countBridgesAndRoads(4, 4) == std::make_pair(1LL, 1LL)); // one triangle + one pendant
    assert(countBridgesAndRoads(4, 5) == std::make_pair(1LL, 0LL)); // complete K4

    // n=5
    assert(countBridgesAndRoads(5, 4) == std::make_pair(1LL, 4LL)); // tree
    assert(countBridgesAndRoads(5, 5) == std::make_pair(1LL, 2LL)); // one triangle, two bridges
    assert(countBridgesAndRoads(5, 6) == std::make_pair(1LL, 0LL)); // two triangles

    // n=6
    assert(countBridgesAndRoads(6, 5) == std::make_pair(1LL, 5LL));
    assert(countBridgesAndRoads(6, 6) == std::make_pair(1LL, 3LL)); // extra=1 -> 5-2=3
    assert(countBridgesAndRoads(6, 7) == std::make_pair(1LL, 1LL)); // extra=2 -> 5-4=1
    assert(countBridgesAndRoads(6, 8) == std::make_pair(1LL, 0LL)); // extra=3 > floor(5/2)=2

    // Large n
    assert(countBridgesAndRoads(1000000000, 0) == std::make_pair(1000000000LL, 0LL));
    assert(countBridgesAndRoads(1000000000, 999999999) == std::make_pair(1LL, 999999999LL));
    assert(countBridgesAndRoads(1000000000, 1000000000) == std::make_pair(1LL, 999999998LL));
    // m = n-1 + floor((n-1)/2) for n=1e9 -> n-1=999999999, floor/2=499999999, m=1499999998
    assert(countBridgesAndRoads(1000000000, 1499999998) == std::make_pair(1LL, 1LL));
    assert(countBridgesAndRoads(1000000000, 1499999999) == std::make_pair(1LL, 0LL));

    return 0;
}
